from typing import List

def minObstacleRemoval(matrix: List[List[str]]) -> int:
    m, n = len(matrix), len(matrix[0])
    shape = [(r, c) for r in range(m) for c in range(n) if matrix[r][c] in ('*', '|')]
    if not shape:
        return 0
    drop = (m - 1) - max(r for r, _ in shape)       # 整体下落的格数
    swept = set()
    for r, c in shape:
        for k in range(1, drop + 1):                # 该格经过的所有位置
            swept.add((r + k, c))
    return sum(1 for r, c in swept if matrix[r][c] == '#')
